def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)

    max_length = max((len(content) for content in cells.values()), default=0)
    sys.setrecursionlimit(
        max(sys.getrecursionlimit(), 20 * (len(cells) + max_length) + 10000)
    )

    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/(),:=<>]")
    values = {}
    active = set()

    def parse(content):
        tokens = token_pattern.findall(content[1:])
        pos = 0

        def expression():
            nonlocal pos
            node = term()
            while pos < len(tokens) and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = (op, node, term())
            return node

        def term():
            nonlocal pos
            node = unary()
            while pos < len(tokens) and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = (op, node, unary())
            return node

        def unary():
            nonlocal pos
            if tokens[pos] == "-":
                pos += 1
                return ("neg", unary())
            return atom()

        def atom():
            nonlocal pos
            token = tokens[pos]
            pos += 1

            if token.isdigit():
                return ("number", int(token))

            if token == "(":
                node = expression()
                pos += 1  # )
                return node

            if token == "IF":
                pos += 1  # (
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1  # ,
                then = expression()
                pos += 1  # ,
                otherwise = expression()
                pos += 1  # )
                return ("if", op, left, right, then, otherwise)

            if token in ("SUM", "MIN", "MAX"):
                pos += 1  # (
                args = []
                while True:
                    if (
                        pos + 1 < len(tokens)
                        and tokens[pos + 1] == ":"
                    ):
                        args.append(("range", tokens[pos], tokens[pos + 2]))
                        pos += 3
                    else:
                        args.append(expression())
                    if tokens[pos] == ")":
                        pos += 1
                        break
                    pos += 1  # ,
                return ("function", token, args)

            return ("cell", token)

        return expression()

    def get_cell(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return "#CYCLE!"

        active.add(name)
        content = cells[name]
        if content.startswith("="):
            result = evaluate(parse(content))
        else:
            result = int(content)
        active.remove(name)
        values[name] = result
        return result

    def evaluate(node):
        kind = node[0]

        if kind == "number":
            return node[1]

        if kind == "cell":
            return get_cell(node[1])

        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value

        if kind in ("+", "-", "*", "/"):
            left = evaluate(node[1])
            if isinstance(left, str):
                return left
            right = evaluate(node[2])
            if isinstance(right, str):
                return right
            if kind == "+":
                return left + right
            if kind == "-":
                return left - right
            if kind == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient

        if kind == "if":
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right

            op = node[1]
            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right
            return evaluate(node[4] if condition else node[5])

        function, args = node[1], node[2]
        result = None

        def add(value):
            nonlocal result
            if result is None:
                result = value
            elif function == "SUM":
                result += value
            elif function == "MIN":
                result = min(result, value)
            else:
                result = max(result, value)

        for arg in args:
            if arg[0] == "range":
                start, end = arg[1], arg[2]
                left, right = sorted((ord(start[0]), ord(end[0])))
                top, bottom = sorted((int(start[1:]), int(end[1:])))
                for row in range(top, bottom + 1):
                    for col in range(left, right + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            value = get_cell(name)
                            if isinstance(value, str):
                                return value
                            add(value)
            else:
                value = evaluate(arg)
                if isinstance(value, str):
                    return value
                add(value)

        return 0 if result is None else result

    return {name: get_cell(name) for name in cells}
